const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else if (raw.args !== undefined) {
  args = typeof raw.args === 'string' ? JSON.parse(raw.args) : raw.args;
} else {
  args = raw;
}

const nombre   = String(args.nombre   || '').trim();
const telefono = String(args.telefono || '').trim().replace(/\D/g, '');

if (!nombre) {
  return [{ json: { error: 'nombre_requerido', derivado: false,
    mensaje: 'No pude registrar la derivacion: falta el nombre del paciente.' }}];
}
if (!/^\d{9}$/.test(telefono)) {
  return [{ json: { error: 'telefono_invalido', derivado: false,
    mensaje: 'El telefono no parece correcto. Me puedes repetir los nueve digitos?' }}];
}

return [{ json: { nombre, telefono } }];
